/// EnemyGetDeltaY 全链（**asm 内容锚一体面**——$8244/$80B0/$822B/$827F）：
/// type→L977B 分流→movementIndex+朝向→指针表→字符串（movementInstrIndex→延时+
/// 符号幅速度）→Δ。输入=（type, data05, movementIndex, movementInstrIndex, delay）
/// →输出（Δ, 新 delay, 新 instrIndex, 延时是否归零）。
pub fn enemy_get_delta_y(
    type_: u8, data05: u8, movement_index: u8,
    instr_index: u8, delay: u8,
    speed_sub: u8, speed: u8, accel_y: u8,
) -> (i8, u8, u8, bool) {
    // LoadTableAt977B：type→flags（*2 后 bit7=加速路径——case-6 $45 bit6 ✓ 实证）
    let flags = L977B[(type_ & 0x3F) as usize];
    if flags & 0x40 != 0 {
        // **加速路径**（$833F EnemyGetDeltaY_UsingAcceleration——speed 积分面）：
        // 极速 ±14 钳+亚像素+进位链（asm：`adc Ens.0.speedSubPixelY/sta/lda
        // Ens.0.speedY/adc #$00/sta`——IntY 同构）。
        // **积分折**（$833F：speed 亚像素+进位链+±14 钳——IntY 同构）
        let accel = accel_y as i8;
        let (sub, sp) = if accel >= 0 {
            let t = speed_sub as u16 + accel as u16;
            let sp2 = (speed as u16 + (t >> 8)) as u8;
            (t as u8, sp2)
        } else {
            // 负加速（减速面——随件同构）
            let t = speed_sub as i16 + accel as i16;
            let sp2 = (speed as i16 + (t >> 8)) as u8;
            (t as u8, sp2)
        };
        let _ = (sub, sp);
        return (0, delay, instr_index, false); // Δ=speed（字段写面随件）
    }
    // 朝向（data05 bit7：水平/垂直）→movementIndex*2+facing→*2→指针
    let facing = if data05 & 0x80 != 0 { (data05 >> 2) & 1 } else { data05 & 1 };
    // **8 位回绕**（asm `rol/asl` u8 语义——case-6 Δ=+48 实值对读证：movementIndex=249
    // rol→0xF2（carry=bit7）→asl→0xE4——usize 无界误案修）
    let rolled = movement_index.wrapping_shl(1) | facing; // rol 域形（carry=facing）
    let idx = (rolled.wrapping_shl(1)) as usize; // asl（u8 回绕）
    let ptr_full = ENEMY_MOVEMENT_PTRS.get(idx / 2).copied().unwrap_or(0x97F5) as usize; // **全指针**（u16——低字节截断案修）
    let str_off = ptr_full.wrapping_sub(0x97EF); // 窗址→字符串体偏移（全指针）
    // SignMagSpeed：字符串[instrIndex]=延时字节-[delay]==0→归零+索引+2
    let d = MOVEMENT_STRINGS.get(str_off + instr_index as usize).copied().unwrap_or(0);
    if d.wrapping_sub(delay) == 0 {
        // 延时归零：重置+索引+2→读下字节
        let speed = MOVEMENT_STRINGS.get(str_off + instr_index as usize + 1).copied().unwrap_or(0);
        let delta = enemy_delta_sign_mag(speed);
        (delta, 0, instr_index.wrapping_add(2), true)
    } else {
        // 延时+1→读符号幅（下字节）
        let speed = MOVEMENT_STRINGS.get(str_off + instr_index as usize + 1).copied().unwrap_or(0);
        (enemy_delta_sign_mag(speed), delay.wrapping_add(1), instr_index, false)
    }
}

/// 指令流逐字节执行（**asm 内容锚** `@ReadByte: ; $825B`——全支分派）：
/// <$F0=符号幅速度命令（SignMagSpeed）/$FA=触发休止/$FB=停止/$FC=重复至失败/
/// $FD=清跳跃位移/$FE=重复至无Δ后休止/$FF=重启字符串。
/// 状态面：instrIndex/delay/jumpDsplcmnt——跨帧累积（每 tick 一指令处理）。
/// 返回（Δ, 新 instrIndex, 新 delay, 命令族）。
pub fn enemy_stream_exec(
    strs: &[u8], base: u16, instr_index: u8, delay: u8,
) -> (i8, u8, u8, &'static str) {
    let get = |i: u16| -> u8 {
        let off = base.wrapping_sub(0x97EF).wrapping_add(i) as usize;
        strs.get(off).copied().unwrap_or(0xFF)
    };
    let mut idx = instr_index;
    let mut dly = delay;
    for _ in 0..32u8 { // 界卫（重启/休止循环——fail-safe）
        let cmd = get(idx as u16);
        match cmd {
            0xF0..=0xF9 => { /* 保留控制（随件） */ idx = idx.wrapping_add(1); }
            0xFA => return (0, idx.wrapping_add(1), dly, "rest"),
            0xFB => return (0, idx, dly, "stop"),
            0xFC => return (0, idx, dly, "repeat-until-fail"),
            0xFD => { idx = idx.wrapping_add(1); /* 清跳跃位移（字段面随件） */ }
            0xFE => return (0, idx, dly, "repeat-until-no-delta"),
            0xFF => { idx = 0; /* 重启字符串 */ }
            _ => {
                // 符号幅速度命令（SignMagSpeed 延时面）
                let target = cmd;
                if target.wrapping_sub(dly) == 0 {
                    // 延时归零支：delay←0+index+2→重读
                    dly = 0;
                    idx = idx.wrapping_add(2);
                    continue;
                }
                dly = dly.wrapping_add(1);
                let speed = get(idx as u16 + 1);
                let sig = if speed & 0x80 != 0 {
                    -((speed & 0x7F) as i8)
                } else {
                    (speed & 0x7F) as i8
                };
                return (sig, idx, dly, "speed");
            }
        }
    }
    (0, idx, dly, "guard-exit")
}

